import{_ as a,a as p,b as n}from"./chunks/mmad_nongemv_compare.ChZBvmhP.js";import{_ as c,o as t,a as l,b as e}from"./app.DKoEZOcr.js";const d="/ascendc.github.io/pr/5487/assets/mmad_gemv_demo.BuTD1HJT.png",b=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"Mmad计算关键特性说明","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/mmad_compute_key_features"},{"text":"GEMV","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/GEMV"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/GEMV.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/GEMV.md","lastUpdated":1785832713000}'),m={name:"api/SIMD-API/basic_api/cube_compute_ISASI/mmad_compute_key_features/GEMV.md"};function i(o,s,r,_,M,h){return t(),l("div",null,[...s[0]||(s[0]=[e('<div><article class="markdown-body"><h1>GEMV<span id="ZH-CN_TOPIC_0000002538231187"></span></h1><p><strong>特性说明：</strong></p><p>Gemv的核心功能体现为：当矩阵A的维度M取值为1时，接口会自动启用Gemv功能，该操作退化为1×K维度的行向量与K×N维度矩阵之间的乘法运算。</p><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT产品，可以通过设置MmadParams的disableGemv参数为true，将该功能关闭。</p></div><p><strong>特性约束：</strong></p><ol><li><p>1×K矩阵A需满足512B地址对齐，K个数据连续存储；以half类型为例，当K=256时，软件侧可视作16*16分块，配置m=1后硬件解析为1*256向量，可通过LoadData接口将256个half数据从L1 Buffer搬至L0A Buffer。</p></li><li><p>C矩阵是一个（1*N）的向量，当1×N向量被划分为多个1×16子向量时，每个子向量在L0C Buffer中占用1024B。但实际有效数据仅占最低32B或64B。例如，当N=50时，共划分4个1*16子向量，占用4*512B = 2048B，其中有效数据仅为4*32B = 128B。</p></li></ol><p><strong>图1</strong> GEMV模式，矩阵乘示意图</p><p><img src="'+a+'" alt="GEMV模式-矩阵乘示意图" title="GEMV模式-矩阵乘示意图"></p><p><strong>使用优势：</strong></p><p>M=1时自动开启GEMV模式，则矩阵乘法将M方向作为非对齐场景进行处理。GEMV模式相较于非对齐处理方式，搬运数据量更少，性能更好。下面以M=1，K=256，N=32，左右矩阵数据类型为half的矩阵乘示例说明。</p><ul><li><p>GEMV模式</p><p>将A矩阵从L1 Buffer（TPosition:A1）搬运到L0A Buffer（TPosition:A2）时，1*256的向量被当作16*16的矩阵进行处理，调用LoadData接口一次完成16*16分形大小的矩阵搬运。B矩阵的搬运以及矩阵乘计算跟基础场景相同，如下图所示。</p><p><strong>图2</strong> GEMV模式M=1的矩阵乘计算示意图</p><p><img src="'+p+'" alt="GEMV模式M=1的矩阵乘计算示意图" title="GEMV模式M=1的矩阵乘计算示意图"></p></li><li><p>非GEMV模式</p><p>将A矩阵从L1 Buffer（TPosition:A1）搬运到L0A Buffer（TPosition:A2）时，1*256的向量被当作非对齐矩阵数据进行处理，将M方向对齐到32字节后进行搬运。调用LoadData接口每次搬运16*16分形大小的矩阵，一共搬运K/16=16次，导致搬运数据量增加，性能相较于GEMV模式差，如下图所示。</p><p><strong>图3</strong> 非GEMV模式M=1的矩阵乘计算示意图</p><p><img src="'+n+'" alt="非GEMV模式M=1的矩阵乘计算示意图" title="非GEMV模式M=1的矩阵乘计算示意图"></p></li></ul><p><strong>使用示例：</strong></p><p><strong>表1</strong> 示例配置说明</p><table><thead><tr><th>矩阵</th><th>维度大小</th><th>数据类型</th></tr></thead><tbody><tr><td>A</td><td>1 * 4096</td><td>half</td></tr><tr><td>B</td><td>4096 * 256</td><td>half</td></tr><tr><td>C</td><td>1 * 256</td><td>float</td></tr></tbody></table><p>A矩阵为1* 4096的向量，从软件侧可以视为64*64的（针对Ascend 950PR/Ascend 950DT产品为NZ分形）数据，通过LoadData搬运到L0A Buffer上；</p><p>C矩阵为1* 256的向量，共可以划分为16个1 * 16的子向量，占用16 * 1024B = 16384B(f162f32)，其中有效数据仅仅为16 * 64B = 1024B；</p><p><strong>图4</strong> GEMV模式矩阵乘示意图</p><p><img src="'+d+`" alt="GEMV模式-矩阵乘示意图-demo" title="GEMV模式-矩阵乘示意图-demo"></p><p>GEMV功能的完整示例：<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_basic_api/03_matrix_compute/mmad_gemv">GEMV样例</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">MmadParams</span><span class="w"> </span><span class="n">mmadParams</span><span class="p">;</span>
<span class="c1">// 设置m = 1自动开启GEMV能力</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">m</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">n</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">n</span><span class="p">;</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">k</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">k</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Mmad</span><span class="p">(</span><span class="n">c</span><span class="p">,</span><span class="w"> </span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">mmadParams</span><span class="p">);</span>
</code></pre></div><div data-filter="950"><p>针对Ascend 950PR/Ascend 950DT产品，可以通过设置MmadParams的disableGemv参数为true，将该功能关闭，示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="n">AscendC</span><span class="o">::</span><span class="n">MmadParams</span><span class="w"> </span><span class="n">mmadParams</span><span class="p">;</span>
<span class="c1">// 设置m = 1自动开启GEMV能力</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">m</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">n</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">n</span><span class="p">;</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">k</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">k</span><span class="p">;</span>
<span class="c1">// 关闭GEMV</span>
<span class="n">mmadParams</span><span class="p">.</span><span class="n">disableGemv</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="nb">true</span><span class="p">;</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">Mmad</span><span class="p">(</span><span class="n">c</span><span class="p">,</span><span class="w"> </span><span class="n">a</span><span class="p">,</span><span class="w"> </span><span class="n">b</span><span class="p">,</span><span class="w"> </span><span class="n">mmadParams</span><span class="p">);</span>
</code></pre></div></div></article></div>`,1)])])}const f=c(m,[["render",i]]);export{b as __pageData,f as default};
